const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centralValley = ee.Geometry.Polygon([
    [-122.5, 36.5],
    [-121.0, 36.5], 
    [-121.0, 40.5],
    [-122.5, 40.5],
    [-122.5, 36.5]
  ]);

  const startDate = '2022-10-01';
  const endDate = '2023-03-31';

  // 2. Data Acquisition - CHIRPS precipitation data
  const precipCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(centralValley);

  const precipSize = precipCol.size().getInfo();
  console.log(`Precipitation images: ${precipSize}`);

  if (precipSize === 0) {
    console.log("No precipitation data found.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over the period
  const totalPrecip = precipCol.sum();

  // Check valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: centralValley,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid precipitation pixels.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation and convert mm to inches
  const meanPrecip = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const inchesPrecip = meanPrecip / 25.4; // Convert mm to inches

  // 5. Validation & Final Answer
  console.log(`Mean precipitation: ${inchesPrecip.toFixed(2)} inches`);
  console.log(`Pixels analyzed: ${pixelCount}`);

  if (inchesPrecip === null || isNaN(inchesPrecip) || inchesPrecip < 0 || inchesPrecip > 100) {
    console.log("<answer>C3</answer>");
  } else if (inchesPrecip >= 15) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
